import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

function Settings() {
  const navigate = useNavigate();  // 설정이 끝나면 채팅 화면으로 이동하기 위해 사용

  const [personality, setPersonality] = useState('T');
  const [gender, setGender] = useState('M');
  const [message, setMessage] = useState('');

  // 설정 저장 함수
  const saveSettings = async () => {
    if (!personality || !gender) {
      setMessage('모든 필드를 선택해주세요');
      return;
    }

    try {
      const response = await fetch('http://localhost:8000/settings', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ personality, gender }),
      });

      if (!response.ok) {
        throw new Error('설정 업데이트 오류');
      }

      const data = await response.json();
      setMessage(data.message || '설정이 성공적으로 업데이트되었습니다');

      // 설정이 완료되면 채팅 화면으로 이동
      navigate("/chat");
    } catch (error) {
      setMessage('설정 업데이트 오류: ' + error.message);
    }
  };

  return (
    <div>
      <h1>Chatbot Settings</h1>
      <div>
        <label>
          성격:
          <select value={personality} onChange={(e) => setPersonality(e.target.value)}>
            <option value="">--선택--</option>
            <option value="T">현실적</option>
            <option value="F">감성적</option>
          </select>
        </label>
      </div>
      <div>
        <label>
          Gender:
          <select value={gender} onChange={(e) => setGender(e.target.value)}>
            <option value="">--선택--</option>
            <option value="M">남자</option>
            <option value="W">여자</option>
          </select>
        </label>
      </div>
      <button onClick={saveSettings}>설정 완료</button>
      {message && <p>{message}</p>}
    </div>
  );
}

export default Settings;
